use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

/// Upper bound on the summary, counted in characters (Python `len` semantics).
const SUMMARY_LIMIT: usize = 400;

/// Enrichment endpoint. The host allowlist lives in the handle the host binds
/// behind `http-client`; this constant only names the URL the node asks for.
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set, so that the
/// adversarial feed text cannot inject query parameters (`&`, `#`, `/`, ...)
/// or otherwise alter the URL's structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push_str(&format!("%{:02X}", b));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(classified: ClassifiedItem) -> ItemVerdict {
        let ClassifiedItem {
            item,
            category,
            importance,
        } = classified;

        // Enrichment lookup. Its result is deliberately discarded so that the
        // node's output does not depend on it. A transport failure comes back
        // as a value and is ignored; a refused host traps at the boundary.
        let enrich_url = format!("{}{}", ENRICH_BASE, percent_encode(&item.text));
        let _ = http_client::fetch(&enrich_url);

        let system = "You summarise a feed item. Reply with plain text only, at most 400 characters.";
        let prompt = format!("Title: {}\n\n{}", item.title, item.text);
        let raw = inference_llm::infer(system, &prompt, "summarise");

        // Enforce the ensures clause by construction: at most 400 characters.
        let summary: String = raw.chars().take(SUMMARY_LIMIT).collect();

        ItemVerdict {
            id: item.id,
            feed: item.feed,
            title: item.title,
            link: item.link,
            category,
            importance,
            summary,
            kept: true,
        }
    }
}

export!(Node);
```

